UPDATE LGCOM_BOARD_N
   SET bulletin_board_inquiry_count = (NVL(bulletin_board_inquiry_count,0) + 1)
 WHERE bulletin_board_id = #{bulletinBoardId}
   AND bulletin_board_no = #{bulletinBoardNo}

UPDATE LGCOM_BOARD_N


   SET bb_reply_level_depth = bb_reply_level_depth + 1


   SET bb_reply_level_depth = bb_reply_level_depth - 1


     , last_updated_by      = #{USER_SESSION.applicationUserId}
     , last_update_date     = SYSDATE
 WHERE bulletin_board_no    = #{bulletinBoardParentId}

UPDATE LGCOM_BOARD_ATTACH_FILE_N
   SET use_flag          = 'N'
     , last_updated_by   = #{USER_SESSION.applicationUserId}
     , last_update_date  = SYSDATE
 WHERE bulletin_board_no = #{bulletinBoardNo}

UPDATE LGCOM_BOARD_ATTACH_FILE_N
   SET use_flag          = 'N'
     , last_updated_by   = #{USER_SESSION.applicationUserId}
     , last_update_date  = SYSDATE
 WHERE file_seq_no       = #{fileSeqNo}
   AND bulletin_board_no = #{bulletinBoardNo}
